public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, 
    List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (!line.startsWith("//") && !line.isEmpty()) {
                String[] cols = line.split("\\|");
                if (cols.length < 2) continue;
                long timestamp = Long.parseLong(cols[0]);
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, line.substring(cols[1].length() + 1));
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range.contains(timestamp)) {
                        threadSnapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
    }
    return threadSnapshots;
}
